//! The printer catalogue: what each model can do.
//!
//! The table itself is generated by `build.rs` from `vendor/devices.json`, a
//! vendored snapshot of NIIMBOT's own device registry. That file is the single
//! upstream everyone in this ecosystem copies from - the third-party model
//! tables in circulation are all derived from it, so they corroborate each other
//! only in the sense that a photocopy corroborates its original.
//!
//! # What is measured and what is derived
//!
//! `printhead_px` is **derived**, as `ceil(print_width_mm x dots_per_mm)`. It
//! agrees with every published figure that can be checked independently, but
//! two third-party tables disagree with each other on roughly a dozen models -
//! D11_H at 142 against 178, K4 at 832 against 656 - and only a full-width test
//! print on real hardware can settle those. Nothing here should be treated as
//! measured until it has been.

use crate::error::ProtoError;

/// Which axis of the canvas runs along the print head.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PrintDirection {
    /// The canvas *width* is the printhead axis; rows pack straight.
    Top,
    /// The canvas *height* is the printhead axis; the encoder rotates 90°.
    ///
    /// The whole 96-dot D11/D110/B16/B18 family is like this, which is why a
    /// 12 mm label reads as a landscape strip rather than a portrait one.
    Left,
}

/// What kind of tag, if any, the printer can read.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RfidKind {
    None,
    Label,
    Ribbon,
    Both,
}

/// How the printer senses where one label ends and the next begins.
///
/// Codes are the vendor's own, recovered from the NIIMBOT app's device registry
/// and resolved to English through its own localisation file.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LabelType {
    Gap,
    Black,
    Continuous,
    Hole,
    Transparent,
    PvcTag,
    BlackMarkGap,
    HeatShrinkTube,
    /// A code outside the known set. Kept rather than rejected so a firmware
    /// that grows a new sensing mode does not make the model unusable.
    Unknown(u8),
}

impl LabelType {
    pub const fn from_code(c: u64) -> LabelType {
        match c {
            1 => LabelType::Gap,
            2 => LabelType::Black,
            3 => LabelType::Continuous,
            4 => LabelType::Hole,
            5 => LabelType::Transparent,
            6 => LabelType::PvcTag,
            10 => LabelType::BlackMarkGap,
            11 => LabelType::HeatShrinkTube,
            other => LabelType::Unknown(other as u8),
        }
    }

    pub const fn code(self) -> u8 {
        match self {
            LabelType::Unknown(c) => c,
            LabelType::Gap => 1,
            LabelType::Black => 2,
            LabelType::Continuous => 3,
            LabelType::Hole => 4,
            LabelType::Transparent => 5,
            LabelType::PvcTag => 6,
            LabelType::BlackMarkGap => 10,
            LabelType::HeatShrinkTube => 11,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            LabelType::Gap => "Gap",
            LabelType::Black => "Black mark",
            LabelType::Continuous => "Continuous",
            LabelType::Hole => "Hole",
            LabelType::Transparent => "Transparent",
            LabelType::PvcTag => "PVC tag",
            LabelType::BlackMarkGap => "Black mark gap",
            LabelType::HeatShrinkTube => "Heat-shrink tube",
            LabelType::Unknown(_) => "Unknown",
        }
    }
}

/// Who actually makes the printer.
///
/// The vendor's registry calls this `interfaceType`, and it selects a **protocol
/// family**, not merely a brand. The official Android SDK carries separate
/// `SNBCFactory` / `ZicoxFactory` / `DetongFactory` classes with their own
/// `PrintTask` implementations alongside the NIIMBOT one, and its framing class
/// is named `NiimbotFrame` - so the rebadged units do not speak what the rest of
/// this crate implements.
///
/// relabel warns rather than refuses: nobody has reported *trying* one of these
/// with a third-party client, and a clear failure is more useful than a
/// pre-emptive block.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Vendor {
    Niimbot,
    Snbc,
    Zkc,
    Daozhen,
}

impl Vendor {
    /// Whether this crate's protocol applies at all.
    pub fn speaks_niimbot(self) -> bool {
        matches!(self, Vendor::Niimbot)
    }
}

/// What the printer does when the loaded roll has no recognised tag.
///
/// Advisory only: it drives the wording of a warning, never a refusal to print.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaperPolicy {
    Normal,
    /// Prints, but clamps the density to its lowest useful setting - which is
    /// why a third-party roll often comes out nearly blank rather than not at
    /// all.
    LowDensity2,
    Forbid,
}

/// Everything the protocol layer needs to know about one printer.
#[derive(Debug, Clone, Copy)]
pub struct ModelSpec {
    pub name: &'static str,
    pub series: &'static str,
    /// The ids this model reports for `PrinterInfo` sub-type 8. Usually one.
    pub wire_ids: &'static [u16],
    pub dpi: u16,
    /// Derived, not measured. See the module note.
    pub printhead_px: u16,
    pub print_width_mm: u16,
    pub min_label_width_mm: u16,
    /// The widest media the printer accepts, which is not the same as the widest
    /// area it can print on.
    pub media_width_mm: u16,
    pub max_label_mm: u16,
    pub default_label_mm: (u16, u16),
    /// `(min, max, default)`. A hard-coded 1..5 slider is wrong for a large
    /// minority of the catalogue.
    pub density: (u8, u8, u8),
    pub direction: PrintDirection,
    pub rfid: RfidKind,
    pub label_types: &'static [LabelType],
    pub supports_calibration: bool,
    pub supports_cutter: bool,
    pub supports_wifi: bool,
    pub vendor: Vendor,
    pub unrecognised_paper: PaperPolicy,
    /// Firmware versions on which the RFID read does not work, from the vendor's
    /// own registry. A printer reporting one of these should not be told its tag
    /// is missing - it is the firmware, not the roll.
    pub rfid_unsupported_fw: &'static [&'static str],
}

impl ModelSpec {
    /// Clamp a requested density into what this model actually accepts.
    pub fn clamp_density(&self, want: u8) -> u8 {
        want.clamp(self.density.0, self.density.1)
    }

    /// Whether this firmware version is one where the RFID read is broken.
    pub fn rfid_broken_on(&self, firmware: &str) -> bool {
        self.rfid_unsupported_fw.contains(&firmware)
    }

    /// The printhead axis in dots, rounded down to a whole byte.
    ///
    /// Rows are packed MSB-first into whole bytes, so a head width that is not a
    /// multiple of 8 cannot be addressed exactly. Rounding down never fires an
    /// element outside the head.
    pub fn printhead_bytes(&self) -> u16 {
        self.printhead_px / 8
    }
}

include!(concat!(env!("OUT_DIR"), "/models.rs"));

/// Find every model that reports this wire id.
///
/// Returns more than one for the ambiguous ids - `512` is both D11 and
/// HI_NB_D11, and they differ in printhead width - so the caller decides rather
/// than being handed a silent guess.
pub fn by_wire_id(id: u16) -> impl Iterator<Item = &'static ModelSpec> {
    MODELS.iter().filter(move |m| m.wire_ids.contains(&id))
}

/// The first model reporting this wire id, if any.
pub fn lookup(id: u16) -> Option<&'static ModelSpec> {
    by_wire_id(id).next()
}

/// Find a model by its marketing name, case-insensitively.
pub fn by_name(name: &str) -> Option<&'static ModelSpec> {
    MODELS.iter().find(|m| m.name.eq_ignore_ascii_case(name))
}

/// What to assume about a printer this table does not know.
///
/// `printhead_px` is deliberately zero rather than a guess. Zero forces the
/// image encoder into its total-count mode, which is the safe branch, and it
/// makes "we do not know how wide this is" visible to the UI instead of
/// producing a plausible-looking wrong number.
pub const UNKNOWN: ModelSpec = ModelSpec {
    name: "Unknown printer",
    series: "",
    wire_ids: &[],
    dpi: 203,
    printhead_px: 0,
    print_width_mm: 0,
    min_label_width_mm: 0,
    media_width_mm: 0,
    max_label_mm: 0,
    default_label_mm: (30, 12),
    density: (1, 5, 3),
    direction: PrintDirection::Top,
    rfid: RfidKind::None,
    label_types: &[LabelType::Gap],
    supports_calibration: false,
    supports_cutter: false,
    supports_wifi: false,
    vendor: Vendor::Niimbot,
    unrecognised_paper: PaperPolicy::Normal,
    rfid_unsupported_fw: &[],
};

/// Convert millimetres to dots at a given resolution.
pub fn mm_to_px(mm: f32, dpi: u16) -> u16 {
    let dpmm = if dpi >= 300 { 11.811_024 } else { 8.0 };
    (mm * dpmm).round().max(0.0) as u16
}

/// Convert dots to millimetres.
pub fn px_to_mm(px: u16, dpi: u16) -> f32 {
    let dpmm = if dpi >= 300 { 11.811_024 } else { 8.0 };
    f32::from(px) / dpmm
}

/// Round a printhead-axis dimension down to a whole number of bytes, refusing
/// anything wider than the head.
pub fn fit_to_head(px: u16, head_px: u16) -> Result<u16, ProtoError> {
    if px == 0 {
        return Err(ProtoError::InvalidValue {
            what: "printhead-axis width of zero",
            value: 0,
        });
    }
    let rounded = px - (px % 8);
    if head_px != 0 && rounded > head_px {
        return Ok(head_px - (head_px % 8));
    }
    Ok(rounded)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_populated() {
        assert!(
            MODELS.len() >= 70,
            "expected the full vendor catalogue, got {}",
            MODELS.len()
        );
    }

    /// The family this project is actually tested against.
    #[test]
    fn d11_family_matches_the_vendor_registry() {
        let d11 = lookup(512).expect("D11 is wire id 512");
        assert_eq!(d11.dpi, 203);
        assert_eq!(d11.printhead_px, 96, "12 mm at 8 dots/mm");
        assert_eq!(d11.direction, PrintDirection::Left);
        assert_eq!(d11.density, (1, 3, 2));
        assert_eq!(d11.rfid, RfidKind::Label);

        let d110 = lookup(2304).expect("D110 is wire id 2304");
        assert_eq!(d110.printhead_px, 96);
        assert!(d110.wire_ids.contains(&2305), "D110 answers on two ids");

        let d101 = lookup(2560).expect("D101 is wire id 2560");
        assert_eq!(d101.printhead_px, 192, "24 mm at 8 dots/mm");
    }

    /// The derived printhead figures that can be checked against published ones.
    #[test]
    fn printhead_widths_match_published_figures() {
        for (name, want) in [
            ("B1", 384u16),
            ("B1 Pro", 567),
            ("B21", 384),
            ("B18", 96),
            ("K3", 640),
            ("ET10", 1600),
        ] {
            let m = by_name(name).unwrap_or_else(|| panic!("{name} is in the catalogue"));
            assert_eq!(m.printhead_px, want, "{name}");
        }
    }

    #[test]
    fn ambiguous_ids_return_every_candidate() {
        // 512 is D11 and HI_NB_D11, and they are not the same printer.
        let n = by_wire_id(512).count();
        assert!(n >= 2, "expected several candidates for 512, got {n}");
        assert!(AMBIGUOUS_WIRE_IDS.contains(&512));
    }

    #[test]
    fn density_is_clamped_per_model() {
        let d11 = lookup(512).unwrap();
        assert_eq!(d11.clamp_density(5), 3, "D11 tops out at 3, not 5");
        assert_eq!(d11.clamp_density(0), 1);
        // The Daozhen block starts at 6, so a default of 3 would be rejected.
        if let Some(b50) = by_name("B50") {
            assert_eq!(b50.clamp_density(3), 6);
        }
    }

    #[test]
    fn rebadged_models_are_flagged_as_a_different_protocol() {
        // The vendor's own SDK carries separate print tasks for these.
        if let Some(b3) = by_name("B3") {
            assert!(!b3.vendor.speaks_niimbot());
        }
        if let Some(b3) = by_name("B3") {
            assert_eq!(b3.vendor, Vendor::Zkc, "B3 is a Zicox unit");
        }
        if let Some(t2s) = by_name("T2S") {
            assert_eq!(t2s.vendor, Vendor::Snbc, "T2S is an SNBC unit");
        }
        if let Some(b50) = by_name("B50") {
            assert_eq!(b50.vendor, Vendor::Daozhen);
        }
        assert!(lookup(512).unwrap().vendor.speaks_niimbot());
    }

    #[test]
    fn d11_records_the_firmwares_where_rfid_is_broken() {
        let d11 = lookup(512).unwrap();
        assert!(d11.rfid_broken_on("1.01"));
        assert!(!d11.rfid_broken_on("3.00"));
    }

    #[test]
    fn unknown_model_forces_the_safe_encoder_branch() {
        assert_eq!(UNKNOWN.printhead_px, 0);
    }

    #[test]
    fn geometry_round_trips() {
        assert_eq!(mm_to_px(12.0, 203), 96);
        assert_eq!(mm_to_px(48.0, 203), 384);
        assert_eq!(mm_to_px(48.0, 300), 567);
        assert_eq!(fit_to_head(100, 96).unwrap(), 96);
        assert_eq!(fit_to_head(90, 96).unwrap(), 88, "rounded down to a byte");
        // An unknown head does not clamp, it only rounds.
        assert_eq!(fit_to_head(1000, 0).unwrap(), 1000);
    }
}
